// Appointment Reminder System: core logic (ported from main.py)

// ---- input normaliser (works for Webhook, Form, WhatsApp, Gmail, Sheets and sample data)
const input = $input.all().flatMap(i => {
  const j = i.json || {};
  if (j.messages && Array.isArray(j.messages)) {           // WhatsApp Trigger
    return j.messages.filter(m => m.text).map(m => ({ from: '+' + m.from, text: m.text.body }));
  }
  if (j.Subject !== undefined || j.From !== undefined) {     // Gmail Trigger (simple)
    return [{ from: (j.From || '').replace(/.*<|>.*/g, ''), subject: j.Subject || '', body: j.snippet || j.text || '' }];
  }
  const b = (j.body !== undefined && j.headers !== undefined) ? j.body : j;   // Webhook wraps payload in body
  if (Array.isArray(b)) return b;
  if (b && Array.isArray(b.items)) return b.items;
  return [b];
});

const parse = t => { t = String(t || '').trim().toLowerCase(); if (!t) return 'none';
  if (/^(1|yes|y|confirm|ok|okay)\b/.test(t)) return 'confirm'; if (/^(2|reschedule|change|move)\b/.test(t) || t.includes('another day')) return 'reschedule';
  if (/^(3|no|cancel)\b/.test(t) || t.includes("can't make it")) return 'cancel'; return 'unclear'; };
const out = [];
for (const b of input) {
  const h = Number(b.hours_until), reply = parse(b.reply);
  if (reply === 'cancel') { if (b.waitlist_name) out.push({ route: 'whatsapp', to: b.waitlist_phone, booking: b.id, message: `Hi ${b.waitlist_name}, a ${b.service} slot just opened. Reply YES to take it.` }); continue; }
  if (h <= 48 && h > 46 && b.sent_48h !== 'yes') out.push({ route: 'whatsapp', to: b.phone, booking: b.id, message: `Hi ${b.name}, reminder: your ${b.service} is in 2 days. Reply 1 to confirm, 2 to reschedule, 3 to cancel.` });
  if (h <= 2 && h > 0 && b.sent_2h !== 'yes') out.push({ route: 'whatsapp', to: b.phone, booking: b.id, message: `Hi ${b.name}, see you soon: your ${b.service} is in about 2 hours.` });
  if (['none', 'unclear'].includes(reply) && h <= 24 && h > 0) out.push({ route: 'call', booking: b.id, message: `${b.id} ${b.name} (${b.service}) has not confirmed: please call ${b.phone}` });
}
return out.map(json => ({ json }));
